from MDAnalysis.lib.util import cached

class TestCacheClass:
    def __init__(self, universe):
        self.universe = universe
        self._cache = dict()
        self.calc_count = 0
        self.calc_count_univ = 0

    @property
    @cached('test_prop')
    def test_prop(self):
        self.calc_count += 1
        return 10.0

    @property
    @cached('test_prop_univ', universe_validation=True)
    def test_prop_univ(self):
        self.calc_count_univ += 1
        return 20.0

# Ensure universe has the required cache structure for the test key
if not hasattr(universe, '_cache'):
    universe._cache = {}
if '_valid' not in universe._cache:
    universe._cache['_valid'] = {}
if 'test_prop_univ' not in universe._cache['_valid']:
    universe._cache['_valid']['test_prop_univ'] = set()

obj = TestCacheClass(universe)

# First access (computes and caches)
v1 = obj.test_prop
v2 = obj.test_prop_univ

# Second access (retrieves from cache)
v3 = obj.test_prop
v4 = obj.test_prop_univ

assert v1 == 10.0 and v3 == 10.0, "Standard cache returned incorrect value"
assert v2 == 20.0 and v4 == 20.0, "Universe-validated cache returned incorrect value"
assert obj.calc_count == 1, f"Standard property computed {obj.calc_count} times instead of 1"
assert obj.calc_count_univ == 1, f"Universe-validated property computed {obj.calc_count_univ} times instead of 1"

print(f"__CHECK__ cached {obj.calc_count}_{obj.calc_count_univ}")

