from MDAnalysis.core.groups import requires
from MDAnalysis.exceptions import NoDataError
import numpy as np

# Define a function that requires 'masses'
@requires('masses')
def compute_total_mass(ag):
    return np.sum(ag.masses)

# Execute the decorated function on an AtomGroup that has masses
total_mass = compute_total_mass(protein)
assert total_mass > 0, "Total mass should be strictly positive"

# Define a function that requires a non-existent attribute to test fail-fast behavior
@requires('nonexistent_attribute_xyz')
def compute_nothing(ag):
    return len(ag)

# Verify that the decorator raises NoDataError when the attribute is missing
raised_no_data_error = False
try:
    compute_nothing(protein)
except NoDataError:
    raised_no_data_error = True

assert raised_no_data_error, "Decorator failed to raise NoDataError for a missing attribute"

print(f"__CHECK__ requires {total_mass:.2f}")
